#!/usr/bin/env node
// Rebuilds ai-context/generated/ from source: database schema (Flyway migrations), REST endpoints
// (Spring mapping annotations), WebSocket message types (MessageType enum) and frontend routes.
// Runs during the Maven build (npm run ai:sync); never edit the generated files by hand.
import { mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..");
const out = join(here, "generated");
const javaRoot = join(root, "src/main/java");
const migrations = join(root, "src/main/resources/db/migration");
const routesDir = join(root, "src/main/frontend/src/routes");

const HEADER = "<!-- Generated by ai-context/sync.mjs. Do not edit; run `npm run ai:sync` in src/main/frontend. -->\n\n";

function walk(dir, predicate) {
  const result = [];
  for (const entry of readdirSync(dir)) {
    const path = join(dir, entry);
    if (statSync(path).isDirectory()) result.push(...walk(path, predicate));
    else if (predicate(path)) result.push(path);
  }
  return result.sort();
}

function posix(path) {
  return path.split(sep).join("/");
}

// ---------------------------------------------------------------------------------------------- schema
function schema() {
  const tables = [];
  const procedures = [];
  const fsms = new Map();
  for (const file of walk(migrations, (p) => p.endsWith(".sql"))) {
    const sql = readFileSync(file, "utf8");
    const name = posix(relative(migrations, file));
    for (const match of sql.matchAll(/CREATE TABLE (\w+) \(([\s\S]*?)\n\);/g)) {
      const columns = [];
      for (const line of match[2].split("\n")) {
        const column = line.trim().match(/^([A-Z][A-Z0-9_]*)\s+([A-Z]+(?:\(\d+\))?)(.*?),?$/);
        if (column && column[1] !== "CONSTRAINT") {
          columns.push({ name: column[1].toLowerCase(), type: column[2], notNull: /NOT NULL/.test(column[3]) });
        }
      }
      const table = match[1].toLowerCase();
      const features = [];
      if (new RegExp(`LIB_attach_header\\('${table}'\\)`).test(sql)) features.push("header");
      const fsm = sql.match(new RegExp(`LIB_attach_fsm\\('${table}', '(\\w+)'\\)`));
      if (fsm) features.push(`fsm ${fsm[1]}`);
      if (new RegExp(`LIB_create_audit\\('${table}'\\)`).test(sql)) features.push("audit");
      tables.push({ table, file: name, columns, features });
    }
    for (const match of sql.matchAll(/CREATE (?:PROCEDURE|FUNCTION) (LIB_\w+)/g)) {
      procedures.push({ name: match[1], file: name });
    }
    for (const match of sql.matchAll(/LIB_fsm_allow\('(\w+)', (NULL|'\w+'), '(\w+)', '(\w+)'\)/g)) {
      const [, fsm, from, action, to] = match;
      if (!fsms.has(fsm)) fsms.set(fsm, []);
      fsms.get(fsm).push(`${from === "NULL" ? "(new)" : from.replaceAll("'", "")} --${action}--> ${to}`);
    }
  }

  let md = `${HEADER}# Database schema\n\n`;
  for (const { table, file, columns, features } of tables) {
    md += `## ${table.toUpperCase()}\n\n${file}${features.length ? ` · ${features.join(" · ")}` : ""}\n\n`;
    md += "| Column | Type | Null |\n|---|---|---|\n";
    for (const column of columns) md += `| ${column.name} | ${column.type} | ${column.notNull ? "" : "yes"} |\n`;
    md += "\n";
  }
  md += "## FSM transitions\n\n";
  for (const [fsm, transitions] of [...fsms.entries()].sort()) {
    md += `### ${fsm}\n\n${transitions.map((t) => `- ${t}`).join("\n")}\n\n`;
  }
  md += "## Library procedures\n\n";
  for (const { name, file } of procedures) md += `- \`${name}\` (${file})\n`;
  return md;
}

// ------------------------------------------------------------------------------------------- endpoints
function endpoints() {
  const rows = [];
  for (const file of walk(javaRoot, (p) => p.endsWith("Controller.java"))) {
    const source = readFileSync(file, "utf8");
    if (!/@RestController/.test(source)) continue;
    const className = source.match(/public class (\w+)/)?.[1] ?? "?";
    const base = source.match(/@RequestMapping\("([^"]*)"\)\s*public class/)?.[1] ?? "";
    const pattern = /@(Get|Post|Put|Patch|Delete)Mapping(?:\((?:value\s*=\s*)?"([^"]*)"\))?[\s\S]*?(?:public|protected)\s+[\w<>, ?]+\s+(\w+)\(/g;
    for (const match of source.matchAll(pattern)) {
      rows.push({ method: match[1].toUpperCase(), path: base + (match[2] ?? ""), handler: `${className}#${match[3]}` });
    }
  }
  rows.sort((a, b) => a.path.localeCompare(b.path) || a.method.localeCompare(b.method));
  let md = `${HEADER}# REST endpoints\n\n| Method | Path | Handler |\n|---|---|---|\n`;
  for (const row of rows) md += `| ${row.method} | \`${row.path}\` | ${row.handler} |\n`;
  return md;
}

// ------------------------------------------------------------------------------------------ ws messages
function wsMessages() {
  const file = walk(javaRoot, (p) => p.endsWith(`${sep}MessageType.java`))[0];
  let md = `${HEADER}# WebSocket message types (protocol v1)\n\nSpec: docs/protocol/ws-v1.md\n\n| Type | Direction |\n|---|---|\n`;
  if (!file) return md;
  for (const match of readFileSync(file, "utf8").matchAll(/^\s+[A-Z_]+\("([^"]+)", "([^"]+)"\)/gm)) {
    md += `| \`${match[1]}\` | ${match[2]} |\n`;
  }
  return md;
}

// ------------------------------------------------------------------------------------------------ routes
function routes() {
  let md = `${HEADER}# Frontend routes\n\n| Path | File |\n|---|---|\n`;
  for (const file of walk(routesDir, (p) => /\.tsx?$/.test(p) && !p.endsWith(".test.tsx"))) {
    const id = readFileSync(file, "utf8").match(/create(?:File|RootRouteWithContext)[^(]*\((?:"([^"]*)")?/);
    const path = id?.[1] ?? "(root)";
    md += `| \`${path}\` | ${posix(relative(routesDir, file))} |\n`;
  }
  return md;
}

mkdirSync(out, { recursive: true });
const outputs = {
  "schema.md": schema(),
  "rest-endpoints.md": endpoints(),
  "ws-message-types.md": wsMessages(),
  "frontend-routes.md": routes(),
};
for (const [name, content] of Object.entries(outputs)) {
  writeFileSync(join(out, name), content);
}
console.log(`ai-context: wrote ${Object.keys(outputs).length} files to ${posix(relative(root, out))}`);
